    assert chk_r(DecisionTreeRegressor(criterion="poisson", max_depth=4, random_state=0), X, Xt, yp, r_pois_nodes, r_pois_feat, r_pois_thr, r_pois_imp, r_pois_val, r_pois_fi, r_pois_pred, r_pois_depth)
